    for b in range(31):
        c = 30 - a - b
        if c < 0:
            continue

        # Check if at least one box has at least 2 coins
        if a >= 2 or b >= 2 or c >= 2:
            # Check if one box has 6 more coins than another
            if a == b + 6 or a == c + 6 or b == a + 6 or b == c + 6 or c == a + 6 or c == b + 6:
                valid_distributions.append((a, b, c))

# Function to calculate the maximum possible winnings for a given guess and distribution
def max_possible_winnings(guess, dist):
    max_winnings = 0
    best_perm = None

    for guess_perm in itertools.permutations(guess):
        winnings = 0
        for g, d in zip(guess_perm, dist):
            if g <= d:
                winnings += g

        if winnings > max_winnings:
            max_winnings = winnings
            best_perm = guess_perm

    return max_winnings, best_perm

# Check all distributions against [0, 6, 12]
guess = [0, 6, 12]
results = []

for dist in valid_distributions:
    for perm in set(itertools.permutations(dist)):
        max_win, best_guess_perm = max_possible_winnings(guess, perm)
        results.append((perm, max_win, best_guess_perm))

# Sort by winnings to find the worst cases
results.sort(key=lambda x: x[1])

print("Top 10 worst distributions for [0, 6, 12] strategy:")
for i, (dist, winnings, best_perm) in enumerate(results[:10]):
    print(f"{i+1}. Distribution: {dist}, Maximum winnings: ${winnings*1000}, Best guess arrangement: {best_perm}")

# Double-check the minimum guaranteed winnings
min_winnings = min(results, key=lambda x: x[1])[1]
print(f"\nMinimum guaranteed winnings with [0, 6, 12]: ${min_winnings*1000}")

# Let's also check if there are any other strategies that might be better
