    [0, 6, 12],
    [1, 5, 12],
    [2, 6, 10],
    [3, 6, 9],
    [0, 7, 11],
    [1, 6, 11],
    [0, 5, 13]
]

for guess in strategies:
    min_win = float('inf')
    worst_dist = None

    for dist in valid_distributions:
        for perm in set(itertools.permutations(dist)):
            max_win, _ = max_possible_winnings(guess, perm)

